import { useEffect, useState } from "react";
import { api } from "../api/manuscriptApi";
import { useParams, useNavigate } from "react-router-dom";

export default function ManuscriptForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    title: "",
    abstract: "",
    keywords: "",
    reference_list: "",
    cover_letter: "",
    manuscript_file: null,
    supplementary_materials: [],
    plagiarism_score: 0,
    author_id: "",
    journal_id: "",
    assigned_editor_id: "",
    status: "Submitted"
  });

  useEffect(() => {
    if (method === "edit") {
      api.get(`/${id}`).then((res) => {
        const m = res.data;
        setForm({
          ...m,
          keywords: m.keywords?.join(",") || "",
          manuscript_file: null, // reset file input
          supplementary_materials: [] // reset files
        });
      });
    }
  }, [id, method]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    const fd = new FormData();

    // Append text fields
    fd.append("title", form.title);
    fd.append("abstract", form.abstract);
    fd.append("keywords", form.keywords);
    fd.append("reference_list", form.reference_list);
    fd.append("cover_letter", form.cover_letter);
    fd.append("plagiarism_score", form.plagiarism_score);
    fd.append("author_id", form.author_id);
    fd.append("journal_id", form.journal_id);
    fd.append("assigned_editor_id", form.assigned_editor_id);
    fd.append("status", form.status);

    // Append files
    if (form.manuscript_file) {
      fd.append("manuscript_file", form.manuscript_file);
    }

    if (form.supplementary_materials.length > 0) {
      Array.from(form.supplementary_materials).forEach(file => {
        fd.append("supplementary_materials", file);
      });
    }

    try {
      if (method === "create") await api.post("/", fd);
      else await api.put(`/${id}`, fd);

      navigate("/journal/list");
    } catch (err) {
      console.error("Error submitting manuscript:", err.response?.data || err.message);
      alert("Error submitting manuscript. Check console for details.");
    }
  };

  return (
    <div className="container mt-4">
      <h3>{method === "create" ? "Create Manuscript" : "Edit Manuscript"}</h3>

      <form onSubmit={handleSubmit}>
        <input
          className="form-control mb-2"
          placeholder="Title"
          value={form.title}
          onChange={e => setForm({ ...form, title: e.target.value })}
        />

        <textarea
          className="form-control mb-2"
          placeholder="Abstract"
          value={form.abstract}
          onChange={e => setForm({ ...form, abstract: e.target.value })}
        ></textarea>

        <input
          className="form-control mb-2"
          placeholder="Keywords (comma separated)"
          value={form.keywords}
          onChange={e => setForm({ ...form, keywords: e.target.value })}
        />

        <input
          type="file"
          className="form-control mb-2"
          onChange={e => setForm({ ...form, manuscript_file: e.target.files[0] })}
        />

        <input
          type="file"
          multiple
          className="form-control mb-2"
          onChange={e => setForm({ ...form, supplementary_materials: e.target.files })}
        />

        <select
          className="form-control mb-2"
          value={form.status}
          onChange={(e) => setForm({ ...form, status: e.target.value })}
        >
          <option>Submitted</option>
          <option>Under Review</option>
          <option>Revision Requested</option>
          <option>Revision Submitted</option>
          <option>Accepted</option>
          <option>Published</option>
          <option>Desk Reject</option>
        </select>

        <button className="btn btn-primary">Save</button>
      </form>
    </div>
  );
}
